"""test_v81cf11.py — los 4 tests de v81cf11 (R80f.7–R80f.10) en un archivo (límite de 200 archivos del paquete).
Cada test original corre aislado, como script, en su propio namespace; uno que falla hace fallar todo."""
import os, sys, runpy, tempfile, textwrap
AQUI = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, AQUI)
FUENTES = {}
FUENTES['test_project_data_idioma.py'] = '#!/usr/bin/env python3\n"""test_project_data_idioma.py — R80f.7 (v81cf11): el chequeo de idioma de verificar no marca el VALOR citado del\nplano (nombre propio \'Camino del Rio\') en el bloque PROJECT DATA de Inputs con el rótulo de R80e.121 (\'PROJECT DATA\n(informative - not an input)\'), igual que con el de R80w.44. Sintético; falla con plantilla v81cf10."""\nimport os, sys, tempfile\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport openpyxl\nimport plantilla_excel as P\nd = tempfile.mkdtemp()\nwb = openpyxl.Workbook(); ws = wb.active; ws.title = "Inputs"\nws.cell(40, 1, "PROJECT DATA (informative - not an input)")\nws.cell(41, 1, "Owner / tenant"); ws.cell(41, 2, "Tenant: Chuze Fitness (1011 Camino del Rio South)"); ws.cell(41, 3, "G001")\nms = wb.create_sheet("Material Summary"); ms.append(["x"]); ms.append(["x"])\nms.append(["Material", "Unit", "Net", "Waste %", "Waste", "Purchase", "Selling unit", "Pieces to buy", "Where it comes from", "Yield check (live formula)"])\nwb.create_sheet("Partition Takeoff")\nx = os.path.join(d, "t.xlsx"); wb.save(x)\nerr = P.verificar_excel(x)\nassert not any("Inputs!B41" in e for e in err), [e for e in err if "Inputs" in e]\nprint("test_project_data_idioma OK")\n'
FUENTES['test_markups_vigente_reciente.py'] = '#!/usr/bin/env python3\n"""test_markups_vigente_reciente.py — R80f.7 (v81cf11): con dos resúmenes de markups del MISMO canon (una versión\nanterior y la nueva), la compuerta verifica el más reciente, no el primero en orden alfabético. Sintético; falla con\nmarkups_bluebeam v81cf10."""\nimport json, os, sys, tempfile, time\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport markups_bluebeam as MB\nd = tempfile.mkdtemp()\nc = os.path.join(d, "canon.json"); json.dump({"walls": []}, open(c, "w"))\nsha = MB.sha_archivo(c)\njson.dump({"tool": MB.TOOL, "canon_sha": sha, "pdf": "a_FINAL3.pdf"}, open(os.path.join(d, "markups_FINAL3.json"), "w"))\ntime.sleep(0.05)\njson.dump({"tool": MB.TOOL, "canon_sha": sha, "pdf": "a_FINAL4.pdf"}, open(os.path.join(d, "markups_FINAL4.json"), "w"))\nos.utime(os.path.join(d, "markups_FINAL3.json"), (1, 1))\nr, m = MB.resumen_vigente([d], c)\nassert r and r["pdf"].endswith("a_FINAL4.pdf"), (r, m)\nprint("test_markups_vigente_reciente OK")\n'
FUENTES['test_markups_be117.py'] = '#!/usr/bin/env python3\n"""test_markups_be117.py — R80f.8 / R80f.9 (BE-117): (1) un tramo recto cuya banda difiere del LF en menos de TOL_PT\nse dibuja con el largo del LF (Bluebeam Length = Excel); (2) el SF de Contents = board SF de la fila (board_out.json\njunto al canon); (3) DETAIL de un type con guion completo (A2-3D/A301); (4) leyenda por hoja en el orden del schedule\n(constants.type_order). Sintético; falla con markups_bluebeam v81cf10."""\nimport json, math, os, sys, tempfile\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport markups_bluebeam as MB\nq = MB.ajustar_a_lf([(0, 0), (52.0, 0)], 2.96, 18)\nassert abs(math.dist(*q) - 2.96 * 18) < 1e-6\nassert MB.ajustar_a_lf([(0, 0), (100.0, 0)], 2.96, 18) == [(0, 0), (100.0, 0)]     # diferencia grande: no se toca\nassert MB.cita({"detail": "TYPE A2-3D/A301"}) == "A2-3D/A301"\nd = tempfile.mkdtemp(); os.makedirs(os.path.join(d, "out"))\njson.dump({"caras": [{"wall": "W1", "sf": 100.0}, {"wall": "W1", "sf": 50.5}]}, open(os.path.join(d, "out", "board_out.json"), "w"))\nc = os.path.join(d, "canon.json"); json.dump({"walls": []}, open(c, "w"))\nMB.cargar_board(c)\nassert MB.BOARD_SF == {"W1": 150.5}\nassert "150.5 SF board" in MB.contenido({"id": "W1", "length_ft": 10, "height_ft": 12, "tag": "A3C", "detail": "TYPE A3C/A301"})\no = MB.orden_types({"constants": {"type_order": {"value": ["B1", "A9"]}}}, ["A9", "OTHER FRAMING", "B1"])\nassert o == ["B1", "A9", "OTHER FRAMING"], o\nassert hasattr(MB, "leyendas_por_hoja")\nprint("test_markups_be117 OK")\n'
FUENTES['test_auditoria_entrega.py'] = '#!/usr/bin/env python3\n"""test_auditoria_entrega.py — R80f.10 / BE-117: auditoria_entrega.py compara cada annot del PDF de markups con su\nfila de la Partition Takeoff (TYPE · LF · H · SF · DETAIL · id), la escala /Measure con el rótulo SCALE impreso y el\nLength con el LF; reporta la annot cuyo SF, escala o Length no coincide con el Excel. Sintético; la tool no existe\nen v81cf10."""\nimport json, os, sys, tempfile\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport openpyxl, pymupdf as fitz\nimport markups_bluebeam as MB\nimport auditoria_entrega as AE\nd = tempfile.mkdtemp()\ndoc = fitz.open(); p = doc.new_page(width=1000, height=700)\np.insert_text((50, 650), "FLOOR PLAN  SCALE: 1/4\\" = 1\'-0\\"", fontsize=10)\ndef annot(nm, pts, content):\n    a = p.add_polyline_annot(pts); a.set_info(title="Take-off", subject="A3C", content=content); a.update()\n    MB._nm(doc, a, "TO-" + nm); MB._measure(doc, a, 18.0)\nannot("W1", [(100, 100), (100 + 18 * 10, 100)], "A3C · 10.00 LF · H 12\'-0\\" · 240.0 SF board · A3C/A301 · W1")\nannot("W2", [(100, 200), (100 + 18 * 11, 200)], "A3C · 10.00 LF · H 12\'-0\\" · 999.0 SF board · A3C/A301 · W2")\npdf = os.path.join(d, "m.pdf"); doc.save(pdf)\nwb = openpyxl.Workbook(); wb.active.title = "Inputs"\nws = wb.create_sheet("Partition Takeoff"); ws.append(["t"]); ws.append(["t"]); ws.append([]); ws.append(["h"])\nws.append(["TYPE A3C"])\nws.append(["A3C  #W1  -  x", "W1", 10.0, 12.0, 1, "3-5/8\\"", 16, 240.0, "x", "TYPE A3C/A301", "[DERIVED]"])\nws.append(["A3C  #W2  -  x", "W2", 10.0, 12.0, 1, "3-5/8\\"", 16, 240.0, "x", "TYPE A3C/A301", "[DERIVED]"])\nws.append([None, "SUBTOTAL TYPE A3C", 20.0]); ws.append([None, "TOTAL - PARTITIONS (GRAND TOTAL)", 20.0])\nfor n in ("Material Summary", "Pending Items", "Review Items", "Scope Checklist"):\n    wb.create_sheet(n)\nx = os.path.join(d, "t.xlsx"); wb.save(x)\nc = os.path.join(d, "canon.json"); json.dump({"walls": [{"id": "W1", "sheet": "1"}, {"id": "W2", "sheet": "1"}]}, open(c, "w"))\nres = AE.auditar(x, pdf, c)\nbad = {(r[0][:1], r[1].split()[0]) for r in res if not r[2]}\nassert ("1", "W2") in bad and ("3", "W2") in bad, bad          # SF distinto y Length 11 ft vs LF 10\nassert ("1", "W1") not in bad and ("2", "W1") not in bad and ("3", "W1") not in bad, bad\nprint("test_auditoria_entrega OK")\n'

for nombre, src in FUENTES.items():
    p = os.path.join(AQUI, '_tmp_' + nombre)
    open(p, 'w').write(src)
    try:
        runpy.run_path(p, run_name='__main__')
    except SystemExit as e:
        if e.code not in (None, 0):
            raise SystemExit(f'{nombre}: FALLA ({e.code})')
    finally:
        os.remove(p)
print('test_v81cf11 OK (4 tests)')

